        /// <summary>repr(e): Name(arg, ...).</summary>
        public static string Repr(Exception e, IEnumerable<object?> args, params string[] extra) =>
            Builtins.PyTypeName(e.GetType()) + "(" + string.Join(", ", args.Select(ReprOf).Concat(extra)) + ")";

        /// <summary>repr() that shows a .NET exception the way Python shows an exception: ValueError('bad').</summary>
        public static string ReprOf(object? o)
        {
            if (o is Exception e && o is not IPyRepr)
            {
                string text = Builtins.str(e);
                return Name(e) + "(" + (text.Length > 0 ? Builtins.repr(e is KeyNotFoundException && text.Length > 1 && text[0] == '\'' ? text.Substring(1, text.Length - 2) : text) : "") + ")";
            }
            if (o is IList list && o is not IPyRepr) return "[" + string.Join(", ", list.Cast<object?>().Select(ReprOf)) + "]";
            return Builtins.repr(o);
        }

        /// <summary>
        /// The Python name of an exception's class, as tracebacks print it: the builtin name (KeyError for .NET's
        /// KeyNotFoundException), or module.Name for a class of a Typhon module (__main__.MyError).
        /// </summary>
        public static string QualifiedName(Exception e)
        {
            string name = Name(e);
            var t = e.GetType();
            if (IsLibrary(t)) return name;
            var outer = t;
            while (outer.DeclaringType != null) outer = outer.DeclaringType;
            // (CPython leaves out __main__ and builtins)
            return outer == t || outer.Name == "__main__" ? name : outer.Name + "." + name;
        }

        static bool IsLibrary(Type t) => t.Namespace is string ns && (ns == "System" || ns.StartsWith("System.") || ns.StartsWith("Microsoft.") || ns.StartsWith("Typhon."));

        /// <summary>The Python name of a class: KeyError for .NET's KeyNotFoundException, int for long, a Typhon class's own name.</summary>
        public static string TypeName(Type t) => DotNetNames.TryGetValue(t, out var n) ? n : Builtins.PyTypeName(t);

        static readonly Dictionary<Type, string> DotNetNames = new Dictionary<Type, string>
        {
            [typeof(Exception)] = "Exception", [typeof(ArgumentException)] = "ValueError", [typeof(FormatException)] = "ValueError",
            [typeof(InvalidCastException)] = "TypeError", [typeof(KeyNotFoundException)] = "KeyError",
            [typeof(ArgumentOutOfRangeException)] = "IndexError", [typeof(IndexOutOfRangeException)] = "IndexError",
            [typeof(DivideByZeroException)] = "ZeroDivisionError", [typeof(NotImplementedException)] = "NotImplementedError",
            [typeof(InvalidOperationException)] = "RuntimeError", [typeof(MissingMemberException)] = "AttributeError",
            [typeof(System.IO.FileNotFoundException)] = "FileNotFoundError", [typeof(System.IO.IOException)] = "OSError",
            [typeof(OverflowException)] = "OverflowError", [typeof(ArithmeticException)] = "ArithmeticError",
            [typeof(TimeoutException)] = "TimeoutError", [typeof(OperationCanceledException)] = "CancelledError",
            [typeof(UnauthorizedAccessException)] = "PermissionError", [typeof(System.IO.EndOfStreamException)] = "EOFError",
            [typeof(OutOfMemoryException)] = "MemoryError",
        };

        /// <summary>The Python name of an exception's class (the reverse of the compiler's exception table for .NET's own exceptions).</summary>
        public static string Name(Exception e)
        {
            var t = e.GetType();
            if (t.Namespace is string ns && (ns == "System" || ns.StartsWith("System.") || ns.StartsWith("Microsoft.")))
                return e switch
                {
                    System.IO.EndOfStreamException => "EOFError",
                    OutOfMemoryException => "MemoryError",
                    _ => PyExcInfo.PythonName(e),
                };
            return Builtins.PyTypeName(t);
        }
    }

