        /// <summary>A group like this one with other exceptions (subgroup and split use it).</summary>
        public virtual BaseExceptionGroup derive(IEnumerable excs) => new ExceptionGroup(message, excs);

        static Func<Exception, bool> Matcher(object? condition) => condition switch
        {
            Type t => e => t.IsInstanceOfType(e),
            ITuple tt => e => Enumerable.Range(0, tt.Length).Any(i => tt[i] is Type t2 && t2.IsInstanceOfType(e)),
