        public BaseExceptionGroup? subgroup(object? condition) => split(condition).Item1;

        public (BaseExceptionGroup?, BaseExceptionGroup?) split(object? condition)
        {
            var match = Matcher(condition);
            if (match(this)) return (this, null);
            var yes = new List<Exception>(); var no = new List<Exception>();
            foreach (var e in exceptions)
            {
                if (e is BaseExceptionGroup g)
                {
                    var (m, r) = g.split(condition);
                    if (m != null) yes.Add(m);
                    if (r != null) no.Add(r);
                }
                else if (match(e)) yes.Add(e);
                else no.Add(e);
