        { this.encoding = encoding; this.@object = @object; this.start = start; this.end = end; this.reason = reason; }
        static string Text(string encoding, object? obj, long start, long end, string reason)
        {
            if (end == start + 1 && obj is PyBytes b && start >= 0 && start < b.Count)
                return $"'{encoding}' codec can't decode byte 0x{b[(int)start]:x2} in position {start}: {reason}";
            return $"'{encoding}' codec can't decode bytes in position {start}-{end - 1}: {reason}";
        }
    }
    internal class UnicodeEncodeError : UnicodeError
    {
        public string encoding { get; set; }
        public object? @object { get; set; }
        public long start { get; set; }
        public long end { get; set; }
        public string reason { get; set; }
        public UnicodeEncodeError(string encoding, string @object, long start, long end, string reason)
            : base(Text(encoding, @object, start, end, reason), new object?[] { encoding, @object, start, end, reason })
        { this.encoding = encoding; this.@object = @object; this.start = start; this.end = end; this.reason = reason; }
        static string Text(string encoding, string s, long start, long end, string reason) =>
            end == start + 1 && start >= 0 && start < s.Length
                ? $"'{encoding}' codec can't encode character {CharRepr(s, start)} in position {start}: {reason}"
                : $"'{encoding}' codec can't encode characters in position {start}-{end - 1}: {reason}";
    }
