    // ── the subclasses of OSError (.NET's IOException) ──

    /// <summary>
    /// The base of the OSError subclasses: OSError(errno, strerror[, filename[, winerror[, filename2]]]) sets errno,
    /// strerror and the file names, and str(e) is "[Errno 17] File exists: 'x'". `except OSError` catches them (they are
    /// IOExceptions).
    /// </summary>
    internal class PyOSError : System.IO.IOException, IPyRepr, IPyExceptionArgs
    {
        public PyTuple<object?> args { get; set; }
        public object? errno { get; set; }
        public object? strerror { get; set; }
        public object? filename { get; set; }
        public object? filename2 { get; set; }
        public object? winerror { get; set; }
        public PyOSError() : this(Array.Empty<object?>()) { }
        public PyOSError(string message) : this(new object?[] { message }) { }
        public PyOSError(string message, Exception innerException) : base(message, innerException) { args = new PyTuple<object?>(new object?[] { message }); }
        public PyOSError(params object?[] args) : base(Text(PyExc.Norm(args)))
        {
            var a = PyExc.Norm(args);
            if (a.Length >= 2 && a.Length <= 5)
            {
                errno = a[0]; strerror = a[1];
                if (a.Length >= 3) filename = a[2];
                if (a.Length >= 4) winerror = a[3];
                if (a.Length == 5) filename2 = a[4];
                this.args = new PyTuple<object?>(new[] { a[0], a[1] });
            }
            else this.args = new PyTuple<object?>(a);
        }
        static string Text(object?[] a)
        {
            if (a.Length < 2 || a.Length > 5) return PyExc.Text(a);
            string head = $"[Errno {Builtins.str(a[0])}] {Builtins.str(a[1])}";
            if (a.Length == 5 && a[2] != null && a[4] != null) return $"{head}: {Builtins.repr(a[2])} -> {Builtins.repr(a[4])}";
            if (a.Length >= 3 && a[2] != null) return $"{head}: {Builtins.repr(a[2])}";
            return head;
        }
        public override string Message => base.Message;
        public string __repr__() => PyExc.Repr(this, args);
    }

    internal class BlockingIOError : PyOSError
    {
        public long characters_written { get; set; }
        public BlockingIOError() : base() { }
        public BlockingIOError(string message) : base(message) { }
        public BlockingIOError(string message, Exception innerException) : base(message, innerException) { }
        public BlockingIOError(params object?[] args) : base(PyExc.Norm(args).Length == 3 ? PyExc.Norm(args).Take(2).ToArray() : args)
        { if (PyExc.Norm(args).Length == 3 && PyExc.Norm(args)[2] is long n) characters_written = n; }
    }
